// Type declarations for the kofem_wasm WebAssembly module.
// The actual .js/.wasm files are generated by scripts/build-wasm.sh and are gitignored.

/** Tessellated STEP surface returned as flat typed arrays (binary, no JSON text).
 *  `vertices` is xyz interleaved (length 3·nVerts); `triangles` is three 0-based
 *  vertex indices per triangle (length 3·nTris); `triangleBodyIds` is the
 *  1-based body (CAD solid) index of each triangle (length nTris), matching the
 *  body ids of the volume mesh (issue #353) for per-body colour / highlight /
 *  hide in the geometry view. `triangleFaceIds` is the 1-based CAD face id of
 *  each triangle (length nTris) — the ids {@link KofemModule.split_geometry}
 *  takes, numbered like the volume mesh's `surfaceFaceIds`. `bodyCount` is the
 *  number of solids in the imported shape — 0 when the file held no closed
 *  solid (surface-only geometry that failed sewing). */
export interface StepTessellation {
  vertices: Float32Array
  triangles: Uint32Array
  triangleBodyIds: Uint32Array
  triangleFaceIds: Uint32Array
  bodyCount: number
}

/** Plane cut requested of {@link KofemModule.split_geometry}, JSON-stringified.
 *  "faces" imprints the plane on the listed faces (1-based CAD face ids, as
 *  `triangleFaceIds` reports them), splitting each into several faces of the
 *  same solid. "bodies" cuts the listed solids (1-based; absent or empty: every
 *  body the plane crosses) into separate bodies, bonded again on reload. */
export interface SplitGeometryOptions {
  mode: "faces" | "bodies"
  origin: [number, number, number]
  normal: [number, number, number]
  faceIds?: number[]
  bodyIds?: number[]
}

/** Boolean combination requested of {@link KofemModule.boolean_geometry},
 *  JSON-stringified. The `target` body (1-based) is combined with the `tools`
 *  bodies and the result takes its place; tools are consumed unless
 *  `keepTools` (subtract only) keeps them, bonded to the cut target on reload. */
export interface BooleanGeometryOptions {
  op: "union" | "subtract" | "intersect"
  target: number
  tools: number[]
  keepTools?: boolean
}

/** A place where the surface mesh overlaps itself, so no volume mesh exists.
 *  `positions` holds xyz of 3 corners per overlapping surface element. A "hinge"
 *  is a straight tangent contact between two CAD faces, located exactly in
 *  `hinge` (mm) and repairable with {@link KofemModule.repair_hinges}. A "cone"
 *  holds a full cone face closing at its tip, which Netgen can fail on; repairable
 *  with {@link KofemModule.split_cone_tips}. An "unmeshed" entry is one CAD face
 *  Netgen gave up on, with `positions` from its display tessellation and its
 *  `width` (mm, 2·area/perimeter); a cone tip it gave up on comes as "cone". */
export interface MeshOverlap {
  kind: "hinge" | "cone" | "surface" | "unmeshed"
  faceIds: Int32Array
  bodyId: number
  positions: Float64Array
  width?: number
  hinge?: {
    start: Float64Array
    end: Float64Array
    normal: Float64Array
    length: number
  }
}

/** Hinge repair requested of {@link KofemModule.repair_hinges}, JSON-stringified.
 *  "connect" welds the two sides with a box along each line, "separate" cuts one
 *  out to open a gap. `width` is the box's width across the line in mm. */
export interface RepairHingesOptions {
  op: "connect" | "separate"
  width: number
  hinges: {
    bodyId: number
    start: number[]
    end: number[]
    normal: number[]
  }[]
}

/** FEM volume mesh returned as flat typed arrays (binary, no JSON text — issue #166).
 *  `vertices` is xyz interleaved (length 3·nNodes); `tetrahedra` is four 0-based
 *  vertex indices per tet (length 4·nTets); `bodyIds` is the 1-based body
 *  (CAD solid) index of each tet (issue #353); `surfaceTriangles` is three
 *  0-based vertex indices per boundary triangle; `surfaceFaceIds` is the 1-based
 *  OCC face index of each boundary triangle (one entry per triangle). */
export interface FemMesh {
  vertices: Float64Array
  tetrahedra: Int32Array
  bodyIds: Int32Array
  surfaceTriangles: Int32Array
  surfaceFaceIds: Int32Array
  /** One route per body in `shell_bodies`; absent when none were given. */
  shellRoutes?: ShellRoute[]
  /** The surface mesh of the Shell bodies on the CAD path (KOF-498), with its
   *  own vertex numbering. The arrays above then hold only the bodies meshed
   *  as volumes, and are empty when there are none. */
  midSurface?: MidSurfaceMesh
}

/** The thickest wall that counts as thin: max(max_wall, body_share × the
 *  body's bounding-box diagonal), mm. */
export interface ThinWallRule {
  max_wall: number
  body_share: number
}

/** How a body marked Shell is meshed (KOF-498). On the CAD path its
 *  mid-surface comes from the paired CAD faces; a body this cannot pair keeps
 *  the mesh-based path, and `face` is the first face that does not fit. */
export type ShellRoute =
  | {
      body: number
      path: "cad"
      walls: {
        kind: "planar" | "cylindrical"
        thickness: number
        /** 1-based face ids; `top` is the wall's top side. */
        top: number[]
        bottom: number[]
        sides: number[]
      }[]
    }
  | {
      body: number
      path: "mesh"
      face: number
      reason: ShellRouteReason
    }

export type ShellRouteReason =
  | "no_thin_wall"
  | "no_opposite_face"
  | "varying_thickness"
  | "unsupported_surface"
  | "partial_overlap"

/** `triangles` are wound so each normal points to its wall's top side;
 *  `midFace` indexes `faces` per triangle; `rimEdges` holds
 *  [a, b, sideFace] per rim edge, vertex indices and the CAD side face. */
export interface MidSurfaceMesh {
  vertices: Float64Array
  triangles: Int32Array
  midFace: Int32Array
  /** `topAreaRatio` / `bottomAreaRatio`: the area of each source face per
   *  unit mid-surface area (1 when flat, r_face / r_mid when cylindrical). */
  faces: {
    body: number
    top: number
    bottom: number
    thickness: number
    topAreaRatio: number
    bottomAreaRatio: number
  }[]
  rimEdges: Int32Array
}

/** Runtime interface of the initialised Emscripten/Embind module. */
export interface KofemModule {
  /** Load a STEP or IGES file and tessellate it for display.
   *  @param cad_bytes Raw STEP/IGES file bytes.
   *  @param opts_json JSON `{ deflection_relative?, linear_deflection?, angular_deflection?, format?: "step" | "iges" }`.
   *                   `format` selects the reader (defaults to "step").
   */
  tessellate_step(cad_bytes: Uint8Array, opts_json: string): StepTessellation
  /** Generate a FEM surface mesh + volume mesh directly from the stored STEP geometry
   *  using Netgen's native OCC integration.  Must call tessellate_step first.
   *  Returns `{ overlaps }` instead of a mesh when the surface mesh overlaps itself
   *  or Netgen could not mesh some faces (kind "unmeshed").
   *  @param opts_json JSON `{ max_element_size, min_element_size, grading, second_order, elementsperedge, elementspercurve, optsteps_2d, optsteps_3d, solid_max_sizes?, face_max_sizes?, shell_bodies?, thin_wall? }`;
   *                   `thin_wall` ({@link ThinWallRule}) is required with `shell_bodies`.
   */
  generate_fem_mesh(opts_json: string): FemMesh | { overlaps: MeshOverlap[] }
  /** The {@link ShellRoute} of each body in `shell_bodies`, without meshing.
   *  @param opts_json JSON `{ shell_bodies: number[], thin_wall: ThinWallRule }`. */
  plan_shell_bodies(opts_json: string): ShellRoute[]
  /** Split faces or bodies of the loaded shape with a plane (see
   *  {@link SplitGeometryOptions}) and return the edited geometry as STEP
   *  AP214 bytes. Throws, naming the face or body, when the plane leaves any
   *  requested one whole. Releases the cached shape: load the returned bytes
   *  with tessellate_step before meshing or splitting again.
   *  @param opts_json JSON-stringified {@link SplitGeometryOptions}. */
  split_geometry(opts_json: string): {
    bytes: Uint8Array
    /** Entry j is the old id of new body j+1: a body cut in two appears twice. */
    bodySources: number[]
  }
  /** Combine bodies of the loaded shape with a Boolean (see
   *  {@link BooleanGeometryOptions}) and return the edited geometry as STEP
   *  AP214 bytes. Throws, naming the bodies, when the operation would change
   *  nothing. Releases the cached shape, like split_geometry.
   *  @param opts_json JSON-stringified {@link BooleanGeometryOptions}. */
  boolean_geometry(opts_json: string): { bytes: Uint8Array }
  /** Remove hinges reported by generate_fem_mesh and return the edited geometry
   *  as STEP AP214 bytes. `bodySources[j]` is the old id of new Body j+1: a body
   *  that came apart appears once per piece. Releases the cached shape, like
   *  split_geometry.
   *  @param opts_json JSON-stringified {@link RepairHingesOptions}. */
  repair_hinges(opts_json: string): { bytes: Uint8Array; bodySources: number[] }
  /** Divide cone faces reported by generate_fem_mesh into pieces Netgen can mesh
   *  and return the edited geometry as STEP AP214 bytes. Releases the cached
   *  shape, like split_geometry.
   *  @param opts_json JSON-stringified `{ faceIds: number[] }`. */
  split_cone_tips(opts_json: string): { bytes: Uint8Array }
  /** Remove "unmeshed" faces reported by generate_fem_mesh by extending the faces
   *  around them (OCCT defeaturing) and return the edited geometry as STEP AP214
   *  bytes. The shape changes by about the faces' width. Throws when the gap
   *  can't be closed. Releases the cached shape, like split_geometry.
   *  @param opts_json JSON-stringified `{ faceIds: number[] }`. */
  remove_faces(opts_json: string): { bytes: Uint8Array }
  /** Release the OCCT shape + STEP byte cache from WASM heap.
   *  Call this after meshing is complete to free ~10–30 MB of WASM memory
   *  that is no longer needed.
   */
  free_geometry_cache(): void
}

/** Progress of init(): bytes are the uncompressed engine size. */
export type EngineLoadProgress =
  | { phase: 'downloading'; loaded: number; total: number }
  | { phase: 'compiling'; loaded: number; total: number }
  /** Compiled; emcc instantiates the module and runs its static constructors. */
  | { phase: 'starting' }
  | {
      phase: 'ready'
      /** From the request to the last byte. */
      downloadMs: number
      /** Compilation left after the last byte (it streams alongside the download). */
      compileMs: number
      /** emcc start-up: instantiation and static constructors. */
      instantiateMs: number
      /** WebAssembly linear memory once started. */
      memoryBytes: number
    }

/** The step of init() that failed. */
export type EngineLoadStage = 'download' | 'compile' | 'instantiate'

/** Thrown by init(); the message says what failed, `stage` where. */
export class EngineLoadError extends Error {
  readonly stage: EngineLoadStage
}

export interface ModuleOverrides {
  print?: (text: string) => void
  printErr?: (text: string) => void
  onProgress?: (progress: EngineLoadProgress) => void
}

/** Initialise the WASM module and return it. Must be awaited before using any function. */
export default function init(overrides?: ModuleOverrides): Promise<KofemModule>
